#!/usr/bin/env python3
import copy,sys,json,math
sys.path.insert(0,"/home/wangzijun_p25/liyuhan/phydataset/ase_asset_importer/everyday_bifurcation_72k_T06_T10_v1/scripts")
import build_project as bp
GRAVITY={"g01_moon":[0,0,-1.62],"g02_mars":[0,0,-3.71],"g03_earth":[0,0,-9.81],"g04_high":[0,0,-15.0],"g05_very_high":[0,0,-24.0]}
BG=["bg01_home_ase","bg02_physics_lab","bg03_neutral_studio","bg04_library_shelf"]
def CAMS(bg):
    c={"cam01":{"position":[0.02,-1.78,0.76],"look_at":[0.02,0.0,0.15],"fov_deg":50.0},
       "cam02":{"position":[0.42,-1.72,1.1],"look_at":[0.02,0.0,0.14],"fov_deg":50.0},
       "cam03":{"position":[-1.1,-0.96,1.22],"look_at":[0.02,0.0,0.12],"fov_deg":51.0}}
    if bg=="bg03_neutral_studio": c["cam02"]={"position":[1.5,-1.02,0.7],"look_at":[0.03,0.0,0.14],"fov_deg":50.0}
    if bg=="bg04_library_shelf": c["cam02"]={"position":[1.25,-1.05,0.85],"look_at":[0.02,0.0,0.12],"fov_deg":50.0}
    return c
PEN_H=0.32; PEN_R=0.0105; FBX=-0.223; BASE_C=0.001
def tilt_for(sx):
    x=sx-PEN_R
    t=(PEN_H+0.004-BASE_C)/(x-FBX) if x>FBX else 0
    th=math.degrees(math.atan(t)) if t>0 else 0
    return th
LO,HI,N=0.080,0.217,22
def main():
    bgs=bp.background_map(); cnt=0; err=0
    for bg in BG:
        background=bgs[bg]
        for gid,gvec in GRAVITY.items():
            for i in range(N):
                sx=LO+(HI-LO)*(i/(N-1)) if N>1 else LO
                tilt=tilt_for(sx)
                if not (34<=tilt<=48):
                    err+=1; continue
                bw={"id":"BW_SIDE_V25","name":"t10_supx_sweep","folder_base_x":FBX,"folder_y":0.080,
                    "folder_lean_deg":round(tilt,2),"folder_mass":0.050,"folder_friction":0.72,
                    "pen_mass":0.095,"pen_friction":0.88,"pen_center_outside_m":0.0025,
                    "pen_height":PEN_H,"pen_y_center":True,"support_x":round(sx,4),
                    "tape_start_y":-0.305,"tape_aim_x_offset_m":0.0,"tape_mass":0.18,"tape_friction":0.40,
                    "tape_collision_proxy":"cylinder","tape_collision_width":0.060,"v_roll":1.80,
                    "parameter":["support_x",LO,HI]}
                sid=f"PROD_T10_{bg}_{gid}_supx_p{i:02d}"
                try:
                    cfg=bp.sample_config("pilot",sid,"T10",bw,round(sx,4),background,i%60)
                except Exception as e:
                    err+=1; continue
                so=cfg.setdefault("scene_overrides",{}); so["gravity"]=gvec; so["gravity_id"]=gid
                cfg["seed"]=abs(hash(sid))%(2**31-1)
                for cid,camv in CAMS(bg).items():
                    cc=copy.deepcopy(cfg); cc["render"]["fixed_view"]=camv
                    cc["render"]["save_video"]=str(bp.PROJECT/"outputs"/"production"/f"{sid}__{cid}"/"videos"/f"{sid}__{cid}.mp4")
                    d=bp.PROJECT/"configs"/"production"/f"{sid}__{cid}"; d.mkdir(parents=True,exist_ok=True)
                    (d/"cam01.json").write_text(json.dumps(cc,indent=2)); cnt+=1
    print(f"T10 supx configs 生成={cnt}, err={err}")
if __name__=="__main__": main()

