#!/usr/bin/env python3
# 44-param production config generator: T06/T09/T10 x 4bg x 5gravity x 44traj x 3cam = 7920
import copy,sys,json,hashlib
from pathlib import Path
ROOT=Path("/home/wangzijun_p25/liyuhan/phydataset/ase_asset_importer/everyday_bifurcation_72k_T06_T10_v1")
sys.path.insert(0,str(ROOT/"scripts"))
import build_project as bp
GRAVITY={"g01_moon":[0,0,-1.62],"g02_mars":[0,0,-3.71],"g03_earth":[0,0,-9.81],"g04_high":[0,0,-15.0],"g05_very_high":[0,0,-24.0]}
BG=["bg01_home_ase","bg02_physics_lab","bg03_neutral_studio","bg04_library_shelf"]
def CAMS(bg):
    c={"cam01":{"position":[0.02,-1.78,0.76],"look_at":[0.02,0.0,0.15],"fov_deg":50.0},
       "cam02":{"position":[0.42,-1.72,1.1],"look_at":[0.02,0.0,0.14],"fov_deg":50.0},
       "cam03":{"position":[-1.1,-0.96,1.22],"look_at":[0.02,0.0,0.12],"fov_deg":51.0}}
    if bg=="bg03_neutral_studio": c["cam02"]={"position":[1.5,-1.02,0.7],"look_at":[0.03,0.0,0.14],"fov_deg":50.0}
    if bg=="bg04_library_shelf": c["cam02"]={"position":[1.25,-1.05,0.85],"look_at":[0.02,0.0,0.12],"fov_deg":50.0}
    return c
def b06(): return copy.deepcopy(next(r for r in bp.CATALOG["T06"] if r["id"]=="BW06"))
def b09(): return copy.deepcopy(next(r for r in bp.CATALOG["T09"] if r["id"]=="BW05"))
def b10(): return {"id":"BW_SIDE_V25","name":"prod_t10","folder_base_x":-0.223,"folder_y":0.080,"folder_lean_deg":38.0,
    "folder_mass":0.050,"folder_friction":0.72,"pen_mass":0.095,"pen_friction":0.88,"pen_center_outside_m":0.0025,
    "pen_height":0.32,"pen_y_center":True,"tape_start_y":-0.305,"tape_aim_x_offset_m":0.0,"tape_mass":0.18,"tape_friction":0.40,
    "tape_collision_proxy":"cylinder","tape_collision_width":0.060,"v_roll":3.0,"parameter":["v_roll",0.60,3.0]}
# 44 total per event-bg-gravity. T06/T09 = 3 sweeps(15/15/14). T10 = 2 sweeps(22/22).
def SW(ev):
    # two 1-D sweeps of 22 values each = 44 per cell (one variable moves at a time)
    if ev=="T06": return [("J","impact_force","value",1.0,4.0,22),("gap","gap","key",0.020,0.085,22)]
    if ev=="T09": return [("pull","pull_force","value",10.0,16.0,22),("mu","layer_friction","key",0.20,0.70,22)]
    if ev=="T10": return [("vroll","v_roll","value",0.60,3.0,22),("supx","support_x","key",-0.05,0.28,22)]
def base(ev): return {"T06":b06(),"T09":b09(),"T10":b10()}[ev]
def main():
    bgs=bp.background_map(); cnt=0; errs=0
    for ev in ["T06","T09"]:  # T10 is generated by gen_t10_supx.py (different supx handling)
        b=base(ev); sweeps=SW(ev)
        for bg in BG:
            background=bgs[bg]
            for gid,gv in GRAVITY.items():
                for (lbl,key,mode,lo,hi,n) in sweeps:
                    for i in range(n):
                        # 22-value sweeps: first 15 are the legacy grid (p00..p14,
                        # unchanged values) so already-rendered configs stay valid;
                        # p15..p21 are 7 added midpoint values.
                        if n==22:
                            v=lo+(hi-lo)*((i/14.0) if i<15 else ((i-15+0.5)/14.0))
                        else:
                            v=lo+(hi-lo)*(i/(n-1)) if n>1 else lo
                        bw=copy.deepcopy(b); val=v
                        # both modes: declare which parameter this is (so the scene
                        # picks the right branch) and write the value where the
                        # scene reads it; val is this sweep's own value.
                        bw["parameter"]=[key,lo,hi]
                        bw[key]=v
                        sid=f"PROD_{ev}_{bg}_{gid}_{lbl}_p{i:02d}"
                        try:
                            cfg=bp.sample_config("pilot",sid,ev,bw,val,background,i)
                        except Exception as e:
                            errs+=1
                            if errs<=6: print("ERR",sid,type(e).__name__,str(e)[:160])
                            continue
                        so=cfg.setdefault("scene_overrides",{}); so["gravity"]=gv; so["gravity_id"]=gid
                        # seed from physics content (+ fixed salt) so identical
                        # physics gets an identical seed across labels.
                        _ph=json.dumps({k:cfg.get(k) for k in ("dynamic_objects","runtime_forces","scene_overrides")},sort_keys=True)
                        cfg["seed"]=int(hashlib.sha256((_ph+"|ebb_v1").encode()).hexdigest()[:8],16)%(2**31-1)
                        for cid,camv in CAMS(bg).items():
                            cc=copy.deepcopy(cfg); cc["render"]["fixed_view"]=camv
                            cc["render"]["save_video"]=str(ROOT/"outputs"/"production"/f"{sid}__{cid}"/"videos"/f"{sid}__{cid}.mp4")
                            d=ROOT/"configs"/"production"/f"{sid}__{cid}"; d.mkdir(parents=True,exist_ok=True)
                            (d/"cam01.json").write_text(json.dumps(cc,indent=2)); cnt+=1
    print("configs=",cnt,"errs=",errs)
if __name__=="__main__": main()
